22	/** The server, only if this caller may act on it. */
23	async function ownedServer(userId: string, role: string, serverId: string) {
24	  return db.server.findFirst({
25	    where: role === "ADMIN" ? { id: serverId } : { id: serverId, userId },
26	    select: { id: true, gamePlanId: true },
27	  });
28	}
