30	export async function setServicePreview(serverId: string, form: FormData): Promise<Result> {
31	  const user = await requireUser();
32	
33	  const rl = checkRateLimit(`service-preview:${user.id}`, { max: 12, windowMs: 60_000 });
34	  if (!rl.ok) return { ok: false, error: "Too many uploads. Please slow down." };
35	
36	  const server = await ownedServer(user.id, user.role, serverId);
37	  if (!server) return { ok: false, error: "Service not found." };
38	  // Game servers lead with their game's own key art; there is nothing for a
39	  // custom image to improve on there, and the card never offers the control.
40	  if (server.gamePlanId !== null) {
41	    return { ok: false, error: "Game servers use their game's artwork." };
42	  }
43	
44	  const file = form.get("file");
45	  if (!(file instanceof File)) return { ok: false, error: "No image provided." };
46	  // Cheap guard before buffering the whole body into memory.
47	  if (file.size > MAX_ATTACHMENT_BYTES) return { ok: false, error: "Image is larger than 5 MB." };
48	
49	  const check = validateImageBytes(Buffer.from(await file.arrayBuffer()), file.type);
50	  if (!check.ok) return { ok: false, error: check.error };
51	
52	  // Prisma's Bytes field wants a plain Uint8Array over a definite ArrayBuffer,
53	  // which a Node Buffer's `ArrayBufferLike` doesn't satisfy on its own.
54	  const bytes = new Uint8Array(check.bytes);
55	
56	  await db.servicePreview.upsert({
57	    where: { serverId: server.id },
58	    create: { serverId: server.id, mime: check.mime, bytes },
59	    update: { mime: check.mime, bytes },
60	  });
61	
62	  revalidatePath("/dashboard/services");
63	  return { ok: true };
64	}
