66	export async function clearServicePreview(serverId: string): Promise<Result> {
67	  const user = await requireUser();
68	  const server = await ownedServer(user.id, user.role, serverId);
69	  if (!server) return { ok: false, error: "Service not found." };
70	
71	  await db.servicePreview.deleteMany({ where: { serverId: server.id } });
72	  revalidatePath("/dashboard/services");
73	  return { ok: true };
74	}
