86	/**
87	 * Email an invitation. Only OWNER/ADMIN of the org may invite. **No Membership
88	 * is created here** — the invitee creates it themselves via `acceptInvite`.
89	 *
90	 * Deliberately does NOT look the email up in the User table. The old version
91	 * did, and that single query produced two leaks from one action any signed-in
92	 * customer can call: it answered "does an account exist with this address?"
93	 * (enumeration oracle), and on a hit it created a Membership whose row then
94	 * exposed the invitee's internal `userId` on the team page — the input the
95	 * unauthenticated 2FA oracle needed (QA-PRELAUNCH P0-2). We send the mail and
96	 * learn nothing: the same response comes back whether or not the address has an
97	 * account, and the sender finds out only if the person chooses to accept.
98	 */
99	export async function inviteMember(
100	  orgId: string,
101	  email: string,
102	  role: string,
103	): Promise<{ error?: string; ok?: boolean; message?: string }> {
104	  const user = await requireUser();
105	  const invitedEmail = String(email ?? "").trim().toLowerCase();
106	  if (!invitedEmail || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(invitedEmail)) {
107	    return { error: "Enter a valid email address." };
108	  }
109	  const wantRole = String(role ?? "MEMBER").toUpperCase();
110	  if (!isRole(wantRole) || wantRole === "OWNER") {
111	    // OWNER is assigned only at creation / ownership transfer, never via invite.
112	    return { error: "Choose a role of ADMIN, MEMBER or BILLING." };
113	  }
114	
115	  const actor = await actorMembership(orgId, user.id);
116	  if (!actor || !canAdministerOrg(actor.role)) {
117	    return { error: "You don't have permission to invite members to this organization." };
118	  }
119	
120	  const org = await db.organization.findUnique({ where: { id: orgId }, select: { name: true } });
121	  if (!org) return { error: "Organization not found." };
122	
123	  if (invitedEmail === user.email.toLowerCase()) {
124	    return { error: "You're already a member of this organization." };
125	  }
126	
127	  // Narrow lookup, and the ONLY one allowed here: does this address already have
128	  // a Membership *in this org*? It answers nothing the caller can't already see —
129	  // they administer this org, so the roster and its addresses are theirs to read
130	  // (app/dashboard/team/page.tsx) — and it returns null for a non-member whether
131	  // or not that address has an account, so it is not the enumeration oracle the
132	  // old `db.user.findUnique` was. Saves emailing an invitation that would be a
133	  // no-op on accept.
134	  const alreadyIn = await db.membership.findFirst({
135	    where: { orgId, user: { email: invitedEmail } },
136	    select: { id: true },
137	  });
138	  if (alreadyIn) {
139	    return { error: "That person is already a member of this organization." };
140	  }
141	
142	  // Throttle per inviter. This action sends Nxeon-branded mail to an arbitrary
143	  // address chosen by the caller, so without a cap it is a spam relay and a way
144	  // to bury someone in invitations. Same shape as the login / password-reset
145	  // throttles (lib/rate-limit.ts).
146	  const rl = checkRateLimit(`org-invite:${user.id}`, { max: 10, windowMs: 60 * 60 * 1000 });
147	  if (!rl.ok) {
148	    return {
149	      error: `Too many invitations sent recently. Try again in ${Math.ceil(rl.retryAfterSec / 60)} minute(s).`,
150	    };
151	  }
152	
153	  const token = await signInviteToken({
154	    orgId,
155	    email: invitedEmail,
156	    role: wantRole,
157	    invitedBy: user.id,
158	  });
159	  const base = (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/$/, "");
160	  const acceptUrl = `${base}/dashboard/team/accept?token=${encodeURIComponent(token)}`;
161	
162	  /* RECORD the invite. The token stays the only thing that AUTHORISES — this
163	     row authorises nothing. It exists so an outstanding invite can be listed
164	     and, more importantly, CANCELLED: a signed token is otherwise valid until
165	     it expires, with no way to take it back once sent to the wrong address.
166	     Only the email the inviter typed is stored; the address is still never
167	     resolved to a user id, which is the property the stateless design was
168	     protecting. */
169	  await db.orgInvite.upsert({
170	    where: { orgId_email: { orgId, email: invitedEmail } },
171	    create: {
172	      orgId, email: invitedEmail, role: wantRole, invitedById: user.id,
173	      tokenHash: createHash("sha256").update(token).digest("hex"),
174	      expiresAt: new Date(Date.now() + 7 * 86_400_000),
175	    },
176	    update: {
177	      role: wantRole, invitedById: user.id,
178	      tokenHash: createHash("sha256").update(token).digest("hex"),
179	      expiresAt: new Date(Date.now() + 7 * 86_400_000),
180	      revokedAt: null, acceptedAt: null,
181	    },
182	  }).catch(() => { /* display-only bookkeeping — never block a real invite */ });
183	
184	  const { sendMail, emails } = await import("./mailer");
185	  const tpl = emails.teamInvite({
186	    inviterName: user.name,
187	    teamName: org.name,
188	    acceptUrl,
189	  });
190	  // `template` is passed so the send is categorised in the admin EmailLog viewer
191	  // (same shape as worker/billing.ts:182). No `userId`: we deliberately never
192	  // resolved the address to an account, so there is no id to attribute it to.
193	  const sent = await sendMail({
194	    to: invitedEmail,
195	    subject: tpl.subject,
196	    html: tpl.html,
197	    template: tpl.template,
198	  });
199	  if (!sent) {
200	    // Report the failure instead of claiming the invitation went out. `sendMail`
201	    // returns false (and logs to EmailLog) when SMTP is unconfigured or the send
202	    // throws; a cheerful "Invitation sent." over a dropped email is exactly the
203	    // confidently-wrong surface this codebase keeps getting bitten by.
204	    return { error: "We couldn't send that invitation email. Check mail settings and try again." };
205	  }
206	
207	  await db.auditLog.create({
208	    data: {
209	      userId: user.id,
210	      action: "org.invite_sent",
211	      detail: `${invitedEmail} → ${wantRole}`,
212	    },
213	  });
214	  return {
215	    ok: true,
216	    message: `Invitation emailed to ${invitedEmail}. They join the organization when they accept it — the link expires in ${INVITE_TTL_HOURS} hours.`,
217	  };
218	}
219	
220	/**
221	 * Accept an invitation. This is the ONLY path that creates a Membership for
222	 * someone other than an org's creator, and it runs as the invitee — clicking
223	 * Accept while signed in as the invited address *is* the consent.
224	 *
225	 * Must be triggered by a deliberate click, never on page load: a mutation that
226	 * fires when the emailed URL is merely opened (or prefetched) would join people
227	 * to organizations without their agreement all over again.
228	 *
229	 * Re-checks at redemption time, because the token carries no server-side state:
230	 * the org still exists, the inviter still administers it, the role is still
231	 * sane, and the token's address matches the signed-in account.
232	 */
233	export async function acceptInvite(
234	  token: string,
235	): Promise<{ error?: string; ok?: boolean; orgName?: string; alreadyMember?: boolean }> {
236	  const user = await requireUser();
237	
238	  const claims = await verifyInviteToken(String(token ?? ""));
239	  /* A cancelled invite must stop working. Checked HERE, against the record
240	     written when it was sent — without this, "revoke" would be a button that
241	     changed a row and nothing else, and the signed token would keep letting
242	     someone in for its full seven days. */
243	  if (claims) {
244	    const rec = await db.orgInvite.findUnique({
245	      where: { orgId_email: { orgId: claims.orgId, email: claims.email } },
246	      select: { revokedAt: true },
247	    }).catch(() => null);
248	    if (rec?.revokedAt) {
249	      return { error: "This invitation has been cancelled. Ask for a new one." };
250	    }
251	  }
252	  if (!claims) {
253	    return {
254	      error: "This invitation link is invalid or has expired. Ask the organization owner to send a new one.",
255	    };
256	  }
257	
258	  // Bound to one address, so a forwarded link can't be redeemed by the recipient.
259	  if (claims.email !== user.email.trim().toLowerCase()) {
260	    return {
261	      error: "This invitation was sent to a different email address. Sign in as that account to accept it.",
262	    };
263	  }
264	
265	  if (!isRole(claims.role) || claims.role === "OWNER") {
266	    return { error: "This invitation carries an invalid role and can't be accepted." };
267	  }
268	
269	  const org = await db.organization.findUnique({
270	    where: { id: claims.orgId },
271	    select: { id: true, name: true },
272	  });
273	  if (!org) return { error: "That organization no longer exists." };
274	
275	  // Revocation, given there is no invitation row to delete: an outstanding
276	  // invitation dies the moment its sender loses the right to have sent it.
277	  const inviter = await actorMembership(org.id, claims.invitedBy);
278	  if (!inviter || !canAdministerOrg(inviter.role)) {
279	    return {
280	      error: "Whoever invited you no longer administers this organization, so the invitation is no longer valid.",
281	    };
282	  }
283	
284	  const existing = await actorMembership(org.id, user.id);
285	  if (existing) {
286	    return { ok: true, orgName: org.name, alreadyMember: true };
287	  }
288	
289	  await db.membership.create({
290	    data: { orgId: org.id, userId: user.id, role: claims.role },
291	  });
292	  await db.auditLog.create({
293	    data: {
294	      userId: user.id,
295	      action: "org.invite_accepted",
296	      detail: `${org.name} → ${claims.role}`,
297	    },
298	  });
299	  revalidatePath("/dashboard/team");
300	  return { ok: true, orgName: org.name };
301	}
302	
303	/**
304	 * Change a member's role. Only OWNER/ADMIN act. The owner's own membership is
305	 * pinned to OWNER and cannot be downgraded here.
306	 *
307	 * Takes a `membershipId`, not a `userId`: the client is never sent co-members'
308	 * user ids any more (see app/dashboard/team/page.tsx), so it has none to send
309	 * back. The org is derived from the membership rather than trusted from the
310	 * caller, which also removes the chance of a mismatched (orgId, userId) pair.
311	 */
312	export async function updateMemberRole(
313	  membershipId: string,
314	  role: string,
315	): Promise<{ error?: string; ok?: boolean }> {
316	  const user = await requireUser();
317	  const wantRole = String(role ?? "").toUpperCase();
318	  if (!isRole(wantRole) || wantRole === "OWNER") {
319	    return { error: "Pick a role of ADMIN, MEMBER or BILLING." };
320	  }
321	
322	  const target = await db.membership.findUnique({ where: { id: String(membershipId ?? "") } });
323	  if (!target) return { error: "That person isn't a member of this organization." };
324	
325	  const actor = await actorMembership(target.orgId, user.id);
326	  if (!actor || !canAdministerOrg(actor.role)) {
327	    return { error: "You don't have permission to change roles in this organization." };
328	  }
329	
330	  const org = await db.organization.findUnique({
331	    where: { id: target.orgId },
332	    select: { ownerId: true },
333	  });
334	  if (!org) return { error: "Organization not found." };
335	  if (target.userId === org.ownerId || target.role === "OWNER") {
336	    return { error: "The organization owner's role can't be changed." };
337	  }
338	
339	  await db.membership.update({
340	    where: { id: target.id },
341	    data: { role: wantRole },
342	  });
343	  await db.auditLog.create({
344	    data: {
345	      userId: user.id,
346	      action: "org.member_role_changed",
347	      detail: `${target.userId} → ${wantRole}`,
348	    },
349	  });
350	  revalidatePath("/dashboard/team");
351	  return { ok: true };
352	}
353	
354	/**
355	 * Remove a member. Only OWNER/ADMIN act; the owner can never be removed.
356	 * Keyed by `membershipId` for the same reason as `updateMemberRole`.
357	 */
358	export async function removeMember(
359	  membershipId: string,
360	): Promise<{ error?: string; ok?: boolean }> {
361	  const user = await requireUser();
362	
363	  const target = await db.membership.findUnique({ where: { id: String(membershipId ?? "") } });
364	  if (!target) return { error: "That person isn't a member of this organization." };
365	
366	  const actor = await actorMembership(target.orgId, user.id);
367	  if (!actor || !canAdministerOrg(actor.role)) {
368	    return { error: "You don't have permission to remove members from this organization." };
369	  }
370	
371	  const org = await db.organization.findUnique({
372	    where: { id: target.orgId },
373	    select: { ownerId: true },
374	  });
375	  if (!org) return { error: "Organization not found." };
376	  if (target.userId === org.ownerId || target.role === "OWNER") {
377	    return { error: "The organization owner can't be removed." };
378	  }
379	
380	  await db.membership.delete({ where: { id: target.id } });
381	  await db.auditLog.create({
382	    data: { userId: user.id, action: "org.member_removed", detail: target.userId },
383	  });
384	  revalidatePath("/dashboard/team");
385	  return { ok: true };
386	}
387	
388	/**
389	 * Leave an organization. The owner can't leave their own org (they'd have to
390	 * transfer ownership first — a follow-up), everyone else may.
391	 */
392	export async function leaveOrg(orgId: string): Promise<{ error?: string; ok?: boolean }> {
393	  const user = await requireUser();
394	
395	  const org = await db.organization.findUnique({ where: { id: orgId }, select: { ownerId: true } });
396	  if (!org) return { error: "Organization not found." };
397	  if (org.ownerId === user.id) {
398	    return { error: "As the owner you can't leave — transfer ownership or delete the organization instead." };
399	  }
400	
401	  const membership = await actorMembership(orgId, user.id);
402	  if (!membership) return { error: "You're not a member of this organization." };
403	
404	  await db.membership.deleteMany({ where: { orgId, userId: user.id } });
405	  await db.auditLog.create({
406	    data: { userId: user.id, action: "org.left", detail: orgId },
407	  });
408	  revalidatePath("/dashboard/team");
409	  return { ok: true };
410	}
411	
412	/** Cancel an outstanding invitation. Gated by the same `canAdministerOrg` that
413	 *  authorises sending one — anyone who may invite may un-invite. The token is
414	 *  not revoked (it cannot be, it is stateless and already sent); `acceptInvite`
415	 *  checks this row and refuses, which is what makes the button mean something. */
416	export async function revokeInvite(orgId: string, email: string): Promise<{ ok?: boolean; error?: string }> {
417	  const user = await requireUser();
418	  /* Same two-step the invite path uses: resolve the caller's membership in THIS
419	     org, then ask whether that role may administer it. `canAdministerOrg` takes
420	     a role, not a user — it is the single definition of the permission and both
421	     paths go through it. */
422	  const actor = await actorMembership(orgId, user.id);
423	  if (!actor || !canAdministerOrg(actor.role)) {
424	    return { error: "You don't have permission to manage invitations for this organization." };
425	  }
426	  const r = await db.orgInvite.updateMany({
427	    where: { orgId, email: email.trim().toLowerCase(), acceptedAt: null, revokedAt: null },
428	    data: { revokedAt: new Date() },
429	  });
430	  if (r.count === 0) return { error: "That invitation has already been accepted or cancelled." };
431	  revalidatePath("/dashboard/team");
432	  return { ok: true };
433	}
