114	/** Owner-or-admin account load with the node relation + manager fields. */
115	async function loadOwned(accountId: string) {
116	  const user = await requireUser();
117	  const a = await db.hostingAccount.findUnique({
118	    where: { id: accountId },
119	    include: { node: { select: { sshHost: true, sshPort: true, rootPasswordEnc: true } } },
120	  });
121	  if (!a) return { error: "Account not found." as const };
122	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." as const };
123	  if (a.status !== "ACTIVE") return { error: "The account is still being set up." as const };
124	  return { user, a };
125	}
