127	/** Confirm a target db name actually belongs to THIS account (defence in depth
128	 *  on top of the MySQL grant). Returns the matched row or null. */
129	async function assertOwnedDatabase(accountId: string, dbName: string) {
130	  if (!isValidDbIdentifier(dbName)) return null;
131	  return db.hostingDatabase.findFirst({ where: { accountId, name: dbName } });
132	}
