139	/**
140	 * Make sure the account has a provisioned DB-manager user. Idempotent:
141	 *   - already ready → { ready:true }
142	 *   - has creds but no ACTIVE user yet (or first call) → generate creds if
143	 *     missing, queue ENSURE_DBMGR, report { provisioning:true }
144	 * Owner-or-admin + not-impersonating (this mints a live DB credential on the box).
145	 * SANDBOX: mark ready immediately (no real node).
146	 */
147	export async function ensureDbManager(accountId: string): Promise<DbMgrStatus & { error?: string }> {
148	  const ctx = await loadOwned(accountId);
149	  if ("error" in ctx) return { ready: false, provisioning: false, enabled: false, error: ctx.error };
150	  await assertNotImpersonating();
151	  const { a } = ctx;
152	  if (!isValidUnixUsername(a.username)) return { ready: false, provisioning: false, enabled: false, error: "Account not ready." };
153	
154	  if (SANDBOX) {
155	    if (!a.dbMgrReady) {
156	      await db.hostingAccount.update({
157	        where: { id: a.id },
158	        data: { dbMgrUser: dbMgrUserFor(a.username), dbMgrPassEnc: encryptSecret(newSecret()), dbMgrReady: true },
159	      });
160	    }
161	    return { ready: true, provisioning: false, enabled: true, sandbox: true };
162	  }
163	
164	  if (a.dbMgrReady && a.dbMgrUser && a.dbMgrPassEnc) return { ready: true, provisioning: false, enabled: true };
165	
166	  // Generate + persist the manager credential once (encrypted at rest); the
167	  // worker applies it on the node. Keep the same password across re-queues so the
168	  // stored cred always matches what the node was told.
169	  if (!a.dbMgrUser || !a.dbMgrPassEnc) {
170	    await db.hostingAccount.update({
171	      where: { id: a.id },
172	      data: { dbMgrUser: dbMgrUserFor(a.username), dbMgrPassEnc: encryptSecret(newSecret()), dbMgrReady: false },
173	    });
174	  }
175	  const inFlight = await db.hostingTask.findFirst({ where: { accountId, kind: "ENSURE_DBMGR", status: { in: ["PENDING", "RUNNING"] } } });
176	  if (!inFlight) await db.hostingTask.create({ data: { accountId, kind: "ENSURE_DBMGR" } });
177	  revalidatePath(`/dashboard/hosting/${accountId}`);
178	  return { ready: false, provisioning: true, enabled: true };
179	}
