182	  const ctx = await loadOwned(accountId);
183	  if ("error" in ctx) return { ready: false, provisioning: false, enabled: false, error: ctx.error };
184	  const { a } = ctx;
185	  if (SANDBOX) return { ready: !!a.dbMgrReady, provisioning: false, enabled: true, sandbox: true };
186	  const provisioning = !a.dbMgrReady && !!(await db.hostingTask.findFirst({ where: { accountId, kind: "ENSURE_DBMGR", status: { in: ["PENDING", "RUNNING"] } } }));
187	  return { ready: !!a.dbMgrReady, provisioning, enabled: true };
