204	const SANDBOX_TABLES = ["customers", "orders", "products"];
205	function sandboxResult(sql: string): DbMgrResult {
206	  const s = sql.trim().toLowerCase();
207	  if (s.startsWith("show tables")) {
208	    return { columns: ["Tables_in_demo"], rows: SANDBOX_TABLES.map((t) => [t]), truncated: false, error: null, elapsedMs: 3 };
209	  }
210	  if (s.startsWith("select count(")) {
211	    return { columns: ["n"], rows: [["3"]], truncated: false, error: null, elapsedMs: 2 };
212	  }
213	  if (s.startsWith("select")) {
214	    return {
215	      columns: ["id", "name", "created_at"],
216	      rows: [["1", "Ada Lovelace", "2026-01-02 10:00:00"], ["2", "Grace Hopper", "2026-01-03 11:30:00"], ["3", "Katherine Johnson", "2026-01-04 09:15:00"]],
217	      truncated: false, error: null, elapsedMs: 4,
218	    };
219	  }
220	  return { columns: [], rows: [], truncated: false, error: null, elapsedMs: 2, ok: true };
