223	/** List a database's tables (SHOW TABLES as the scoped user). Owner-or-admin +
224	 *  not-impersonating (it reaches the customer's live data). */
225	export async function dbmgrListTables(accountId: string, dbName: string): Promise<{ error?: string; tables?: string[] }> {
226	  const ctx = await loadOwned(accountId);
227	  if ("error" in ctx) return { error: ctx.error };
228	  await assertNotImpersonating();
229	  const { user } = ctx;
230	  if (!(await assertOwnedDatabase(accountId, dbName))) return { error: "Unknown database." };
231	  if (!rlOk(user.id, accountId)) return { error: "Too many requests — slow down a moment." };
232	  if (SANDBOX) return { tables: SANDBOX_TABLES };
233	  const target = dbTargetFor(ctx.a);
234	  if (!target) return { error: "The database manager is still being prepared." };
235	  const res = await runScopedSql(target, dbName, showTablesSql());
236	  if (res.error) return { error: res.error };
237	  return { tables: res.rows.map((r) => r[0]).filter(Boolean) };
