240	/** One per-column filter the browse grid sends: a real column name + a substring
241	 *  matched with LIKE. Multiple filters are ANDed. */
242	export type DbMgrFilter = { column: string; value: string };
243	export type DbMgrBrowseOpts = {
244	  page?: number;
245	  pageSize?: number;
246	  sortColumn?: string;
247	  sortDir?: "ASC" | "DESC";
248	  /** Per-column LIKE filters (ANDed). Unknown columns are dropped. */
249	  filters?: DbMgrFilter[];
250	  /** A quick-search term ORed (as LIKE) across the table's text columns. */
251	  search?: string;
252	};
253	export type DbMgrBrowseResult = {
254	  error?: string;
255	  columns?: string[];
256	  rows?: string[][];
257	  total?: number | null;
258	  page?: number;
259	  pageSize?: number;
260	  truncated?: boolean;
261	  sortColumn?: string | null;
262	  sortDir?: "ASC" | "DESC";
263	};
264	
265	/** Text-ish column types the global quick-search targets. */
266	const TEXTY_TYPE_RE = /char|text|enum|set|json/i;
267	
268	/** Browse a page of a table's rows. Validates the table by MEMBERSHIP against the
269	 *  db's real table list (so a user can't name a table they can't see), then runs
270	 *  a bounded SELECT + a COUNT. Supports per-column LIKE filters, a global quick
271	 *  search across text columns, sorting, and a chosen page size — all identifiers
272	 *  membership-validated, all values `?`-bound. Owner-or-admin + not-impersonating. */
273	export async function dbmgrBrowseTable(
274	  accountId: string,
275	  dbName: string,
276	  table: string,
277	  opts: DbMgrBrowseOpts = {},
278	): Promise<DbMgrBrowseResult> {
279	  const ctx = await loadOwned(accountId);
280	  if ("error" in ctx) return { error: ctx.error };
281	  await assertNotImpersonating();
282	  const { user } = ctx;
283	  if (!(await assertOwnedDatabase(accountId, dbName))) return { error: "Unknown database." };
284	  if (!isPlausibleTableName(table)) return { error: "Invalid table name." };
285	  if (!rlOk(user.id, accountId)) return { error: "Too many requests — slow down a moment." };
286	  const p = Math.max(0, Math.floor(Number(opts.page) || 0));
287	  const pageSize = clampPageSize(opts.pageSize ?? BROWSE_PAGE_SIZE);
288	  const dir: "ASC" | "DESC" = opts.sortDir === "DESC" ? "DESC" : "ASC";
289	  const search = String(opts.search ?? "").trim();
290	
291	  if (SANDBOX) {
292	    const demo = sandboxResult("select");
293	    return { columns: demo.columns, rows: demo.rows, total: demo.rows.length, page: p, pageSize, truncated: false, sortColumn: opts.sortColumn ?? null, sortDir: dir };
294	  }
295	  const target = dbTargetFor(ctx.a);
296	  if (!target) return { error: "The database manager is still being prepared." };
297	
298	  // Membership check: the table MUST be one the scoped user can actually see.
299	  const listed = await runScopedSql(target, dbName, showTablesSql());
300	  if (listed.error) return { error: listed.error };
301	  const tables = listed.rows.map((r) => r[0]);
302	  if (!tables.includes(table)) return { error: "Unknown table." };
303	
304	  // Load the real columns (name + type) once — the sole source for validating
305	  // every identifier we embed (sort col, filter cols, search cols).
306	  const colsRes = await runScopedSql(target, dbName, showFullColumnsSql(table));
307	  if (colsRes.error) return { error: colsRes.error };
308	  const realCols = colsRes.rows.map((r) => r[0]);
309	  const realSet = new Set(realCols);
310	  const textCols = colsRes.rows.filter((r) => TEXTY_TYPE_RE.test(r[1] ?? "")).map((r) => r[0]);
311	
312	  // Sort column validated by MEMBERSHIP before it can be backtick-quoted.
313	  let order: { col: string; dir: "ASC" | "DESC" } | undefined;
314	  if (opts.sortColumn && realSet.has(opts.sortColumn)) order = { col: opts.sortColumn, dir };
315	
316	  // Per-column filters: keep only real columns; bind each value as `%v%`.
317	  const filterCols: string[] = [];
318	  const filterValues: string[] = [];
319	  for (const f of opts.filters ?? []) {
320	    if (f && realSet.has(f.column) && String(f.value ?? "") !== "") {
321	      filterCols.push(f.column);
322	      filterValues.push(`%${likeEscape(String(f.value))}%`);
323	    }
324	  }
325	  // Global search: OR LIKE across text columns (all columns if none are texty),
326	  // one bound `%term%` per column.
327	  const searchCols = search ? (textCols.length ? textCols : realCols) : [];
328	  const searchValues = searchCols.map(() => `%${likeEscape(search)}%`);
329	
330	  const hasFilter = filterCols.length > 0 || searchCols.length > 0;
331	  const sql = hasFilter
332	    ? filteredBrowseSql(table, filterCols, searchCols, pageSize, p * pageSize, order)
333	    : browseTableSql(table, pageSize, p * pageSize, order);
334	  const params = [...filterValues, ...searchValues];
335	  const res = await runScopedSql(target, dbName, sql, hasFilter ? params : undefined);
336	  if (res.error) return { error: res.error };
337	
338	  const countSql = hasFilter ? countFilteredSql(table, filterCols, searchCols) : countTableSql(table);
339	  const countRes = await runScopedSql(target, dbName, countSql, hasFilter ? params : undefined);
340	  const total = countRes.error ? null : Number(countRes.rows[0]?.[0] ?? "0");
341	  return { columns: res.columns, rows: res.rows, total: Number.isFinite(total as number) ? (total as number) : null, page: p, pageSize, truncated: res.truncated, sortColumn: order?.col ?? null, sortDir: dir };
342	}
