344	/** Escape the LIKE metacharacters `%` and `_` (and the escape char) in a
345	 *  user search term so they match literally inside our `%…%` wrapper. The value
346	 *  is still bound as a `?` param — this only stops a user `%` widening the match. */
347	function likeEscape(s: string): string {
348	  return s.replace(/[\\%_]/g, (c) => `\\${c}`);
349	}
