351	/**
352	 * Run arbitrary SQL scoped to one of the account's databases. The SQL runs through
353	 * the mysql2 protocol driver over an SSH-forwarded channel to the node's localhost
354	 * MySQL (never a `mysql` CLI, never a shell), executed as the scoped manager user —
355	 * MySQL's grant is the hard isolation boundary, and there is no CLI meta-command
356	 * interpreter to abuse. Owner-or-admin + not-impersonating + rate-limited.
357	 */
358	export async function dbmgrRunSql(accountId: string, dbName: string, sql: string): Promise<DbMgrResult> {
359	  const empty: DbMgrResult = { columns: [], rows: [], truncated: false, error: null, elapsedMs: 0 };
360	  const ctx = await loadOwned(accountId);
361	  if ("error" in ctx) return { ...empty, error: ctx.error ?? null };
362	  await assertNotImpersonating();
363	  const { user } = ctx;
364	  if (!(await assertOwnedDatabase(accountId, dbName))) return { ...empty, error: "Unknown database." };
365	  const text = String(sql ?? "").trim();
366	  if (!text) return { ...empty, error: "Enter a SQL statement." };
367	  if (Buffer.byteLength(text, "utf8") > MAX_SQL_BYTES) return { ...empty, error: "That query is too large." };
368	  if (!rlOk(user.id, accountId)) return { ...empty, error: "Too many requests — slow down a moment." };
369	
370	  if (SANDBOX) return sandboxResult(text);
371	  const target = dbTargetFor(ctx.a);
372	  if (!target) return { ...empty, error: "The database manager is still being prepared." };
373	  const res: QueryResult = await runScopedSql(target, dbName, text);
374	  if (res.error) return { ...res, error: res.error };
375	  return { ...res, ok: res.columns.length === 0 };
376	}
