378	/* ─────────────────────── Structure + row editor (parameterized) ──────────────
379	 * These actions power the data-grid's insert / edit / delete and the "structure"
380	 * tab. They share the same isolation as the query surface: owner-or-admin, not
381	 * impersonating, owned db, rate-limited, and — crucially — every statement runs
382	 * through `runScopedSql` as the scoped `<username>_mgr` user over the SSH tunnel.
383	 * User VALUES are always bound as `?` parameters (never string-concatenated);
384	 * user IDENTIFIERS (table + column names) are validated by MEMBERSHIP against the
385	 * live table/column list before they can be backtick-quoted into SQL, so a name
386	 * can only ever be one the scoped user is already permitted to see. */
387	
388	const SANDBOX_STRUCTURE: DbMgrStructure = {
389	  columns: [
390	    { name: "id", type: "int(11)", nullable: false, key: "PRI", default: null, extra: "auto_increment", comment: "", collation: "" },
391	    { name: "name", type: "varchar(255)", nullable: false, key: "", default: null, extra: "", comment: "", collation: "utf8mb4_unicode_ci" },
392	    { name: "created_at", type: "datetime", nullable: true, key: "", default: "CURRENT_TIMESTAMP", extra: "", comment: "", collation: "" },
393	  ],
394	  indexes: [{ name: "PRIMARY", columns: ["id"], unique: true }],
395	  primaryKey: ["id"],
396	};
