398	/** Owner-or-admin + not-impersonating + owned-db + rate-limit + ready-target
399	 *  preamble shared by the live-data actions. Returns a discriminated result. */
400	async function liveTarget(
401	  accountId: string,
402	  dbName: string,
403	): Promise<{ error: string } | { mode: "sandbox" } | { mode: "live"; target: DbNodeTarget }> {
404	  const ctx = await loadOwned(accountId);
405	  if ("error" in ctx) return { error: ctx.error ?? "Request failed." };
406	  await assertNotImpersonating();
407	  if (!(await assertOwnedDatabase(accountId, dbName))) return { error: "Unknown database." };
408	  if (!rlOk(ctx.user.id, accountId)) return { error: "Too many requests — slow down a moment." };
409	  if (SANDBOX) return { mode: "sandbox" };
410	  const target = dbTargetFor(ctx.a);
411	  if (!target) return { error: "The database manager is still being prepared." };
412	  return { mode: "live", target };
413	}
