415	/** Confirm `table` is one the scoped user can actually see (membership check via
416	 *  SHOW TABLES). The lone hard identifier boundary for the DML/structure paths. */
417	async function tableIsVisible(target: DbNodeTarget, dbName: string, table: string): Promise<{ error: string } | { ok: true }> {
418	  if (!isPlausibleTableName(table)) return { error: "Invalid table name." };
419	  const listed = await runScopedSql(target, dbName, showTablesSql());
420	  if (listed.error) return { error: listed.error };
421	  if (!listed.rows.map((r) => r[0]).includes(table)) return { error: "Unknown table." };
422	  return { ok: true };
423	}
