425	/** Fetch a table's structure (columns, indexes, primary key) as the scoped user.
426	 *  Assumes membership has already been asserted for `table`. */
427	async function fetchStructure(target: DbNodeTarget, dbName: string, table: string): Promise<{ error: string } | { structure: DbMgrStructure }> {
428	  const cols = await runScopedSql(target, dbName, showFullColumnsSql(table));
429	  if (cols.error) return { error: cols.error };
430	  // SHOW FULL COLUMNS positional order: Field, Type, Collation, Null, Key, Default, Extra, Privileges, Comment.
431	  const columns: DbMgrColumn[] = cols.rows.map((r) => ({
432	    name: r[0],
433	    type: r[1],
434	    nullable: (r[3] ?? "").toUpperCase() === "YES",
435	    key: r[4] ?? "",
436	    default: r[5] === NULL_SENTINEL ? null : (r[5] ?? null),
437	    extra: r[6] ?? "",
438	    comment: r[8] ?? "",
439	    collation: r[2] === NULL_SENTINEL ? "" : (r[2] ?? ""),
440	  }));
441	
442	  const idx = await runScopedSql(target, dbName, showIndexSql(table));
443	  // SHOW INDEX positional: Table, Non_unique, Key_name, Seq_in_index, Column_name, ...
444	  const byName = new Map<string, { name: string; unique: boolean; cols: Array<{ seq: number; col: string }> }>();
445	  if (!idx.error) {
446	    for (const r of idx.rows) {
447	      const keyName = r[2];
448	      const nonUnique = r[1] === "1";
449	      const seq = Number(r[3] ?? "0") || 0;
450	      const col = r[4];
451	      const entry = byName.get(keyName) ?? { name: keyName, unique: !nonUnique, cols: [] };
452	      entry.cols.push({ seq, col });
453	      byName.set(keyName, entry);
454	    }
455	  }
456	  const indexes: DbMgrIndex[] = [...byName.values()].map((e) => ({
457	    name: e.name,
458	    unique: e.unique,
459	    columns: e.cols.sort((a, b) => a.seq - b.seq).map((c) => c.col),
460	  }));
461	  const primaryKey = indexes.find((i) => i.name === "PRIMARY")?.columns
462	    ?? columns.filter((c) => c.key === "PRI").map((c) => c.name);
463	
464	  return { structure: { columns, indexes, primaryKey } };
465	}
