507	/** INSERT a row. `values` is column→value (null = SQL NULL); unknown columns are
508	 *  dropped, values are bound as `?` params. Owner-or-admin + not-impersonating. */
509	export async function dbmgrInsertRow(accountId: string, dbName: string, table: string, values: Record<string, DbCellValue>): Promise<DbMgrResult> {
510	  const empty: DbMgrResult = { columns: [], rows: [], truncated: false, error: null, elapsedMs: 0 };
511	  const lt = await liveTarget(accountId, dbName);
512	  if ("error" in lt) return { ...empty, error: lt.error };
513	  if (lt.mode === "sandbox") return { ...empty, ok: true };
514	  const vis = await tableIsVisible(lt.target, dbName, table);
515	  if ("error" in vis) return { ...empty, error: vis.error };
516	  const s = await fetchStructure(lt.target, dbName, table);
517	  if ("error" in s) return { ...empty, error: s.error };
518	
519	  const real = new Set(s.structure.columns.map((c) => c.name));
520	  const cols = keepValidColumns(Object.keys(values ?? {}), real);
521	  if (cols.length === 0) return { ...empty, error: "Provide at least one column value." };
522	  const params = cols.map((c) => values[c]);
523	  const res = await runScopedSql(lt.target, dbName, insertRowSql(table, cols), params);
524	  if (res.error) return { ...res, error: res.error };
525	  return { ...res, ok: true };
