528	/** Resolve the WHERE columns that identify an existing row: prefer the PRIMARY
529	 *  KEY (when every PK column is present in `where`), else fall back to every
530	 *  supplied real column. Returns [] when the row can't be safely identified. */
531	function whereColumnsFor(where: Record<string, DbCellValue>, structure: DbMgrStructure, real: Set<string>): string[] {
532	  const supplied = keepValidColumns(Object.keys(where ?? {}), real);
533	  const pk = structure.primaryKey;
534	  if (pk.length > 0 && pk.every((c) => c in (where ?? {}))) return pk;
535	  return supplied;
536	}
