539	 *  new column→value pairs. Both bound as `?` params, LIMIT 1 on the write. */
540	export async function dbmgrUpdateRow(
541	  accountId: string,
542	  dbName: string,
543	  table: string,
544	  where: Record<string, DbCellValue>,
545	  changes: Record<string, DbCellValue>,
546	): Promise<DbMgrResult> {
547	  const empty: DbMgrResult = { columns: [], rows: [], truncated: false, error: null, elapsedMs: 0 };
548	  const lt = await liveTarget(accountId, dbName);
549	  if ("error" in lt) return { ...empty, error: lt.error };
