551	  const vis = await tableIsVisible(lt.target, dbName, table);
552	  if ("error" in vis) return { ...empty, error: vis.error };
553	  const s = await fetchStructure(lt.target, dbName, table);
554	  if ("error" in s) return { ...empty, error: s.error };
