556	  const real = new Set(s.structure.columns.map((c) => c.name));
557	  const setCols = keepValidColumns(Object.keys(changes ?? {}), real);
558	  if (setCols.length === 0) return { ...empty, error: "No changes to save." };
559	  const whereCols = whereColumnsFor(where, s.structure, real);
