588	/** Build a downloadable SQL dump of a single table (CREATE TABLE + a bounded set
589	 *  of INSERTs) via the scoped connection — no root, no mysqldump. Values are
590	 *  escaped by the mysql2 string-escaper. Bounded by the transport's row cap.
591	 *  Owner-or-admin + not-impersonating. */
592	export async function dbmgrExportTable(accountId: string, dbName: string, table: string, format: "sql" | "csv" = "sql"): Promise<{ error?: string; filename?: string; content?: string; mime?: string; truncated?: boolean }> {
593	  const lt = await liveTarget(accountId, dbName);
594	  if ("error" in lt) return { error: lt.error };
595	  if (lt.mode === "sandbox") {
596	    return format === "csv"
597	      ? { filename: `${table}.csv`, content: "id,name\r\n", mime: "text/csv", truncated: false }
598	      : { filename: `${table}.sql`, content: `-- Nxeon DB Studio (sandbox) export of \`${table}\`\n`, mime: "application/sql", truncated: false };
599	  }
600	  const vis = await tableIsVisible(lt.target, dbName, table);
601	  if ("error" in vis) return { error: vis.error };
602	
603	  // CSV: just the data (header + rows), bounded by the transport row cap.
604	  if (format === "csv") {
605	    const data = await runScopedSql(lt.target, dbName, dumpSelectSql(table));
606	    if (data.error) return { error: data.error };
607	    // A truncated export says so IN ITS FILENAME. The SQL dump at least buries a
608	    // `-- rows: … (truncated)` comment in its header; the CSV carried no marker
609	    // at all, so a customer with a 40k-row table downloaded 1,000 rows in a file
610	    // called `wp_posts.csv` and had no way to know. CSV has no comment syntax and
611	    // a marker row would corrupt the data, so the name carries it — the name is
612	    // also the part that survives being emailed to someone else.
613	    return {
614	      filename: data.truncated ? `${table}.first-${data.rows.length}-rows.csv` : `${table}.csv`,
615	      content: toCsv(data.columns, data.rows),
616	      mime: "text/csv",
617	      truncated: data.truncated,
618	    };
619	  }
620	
621	  const create = await runScopedSql(lt.target, dbName, showCreateTableSql(table));
622	  if (create.error) return { error: create.error };
623	  // SHOW CREATE TABLE returns one row: [Table, "Create Table"].
624	  const createStmt = create.rows[0]?.[1] ?? "";
625	
626	  const s = await fetchStructure(lt.target, dbName, table);
627	  if ("error" in s) return { error: s.error };
628	  const colNames = s.structure.columns.map((c) => c.name);
629	
630	  const data = await runScopedSql(lt.target, dbName, dumpSelectSql(table));
631	  if (data.error) return { error: data.error };
632	
633	  const lines: string[] = [];
634	  lines.push(`-- Nxeon DB Studio export`);
635	  lines.push(`-- database: ${dbName}`);
636	  lines.push(`-- table:    ${table}`);
637	  lines.push(`-- generated: ${new Date().toISOString()}`);
638	  lines.push(`-- rows:     ${data.rows.length}${data.truncated ? ` (truncated at ${data.rows.length})` : ""}`);
639	  lines.push("");
640	  lines.push("SET FOREIGN_KEY_CHECKS=0;");
641	  lines.push(`DROP TABLE IF EXISTS ${quoteIdent(table)};`);
642	  lines.push(`${createStmt};`);
643	  lines.push("");
644	  if (data.rows.length > 0) {
645	    const colList = colNames.map((c) => quoteIdent(c)).join(", ");
646	    for (const row of data.rows) {
647	      const vals = row.map((cell) => dumpValueLiteral(cell)).join(", ");
648	      lines.push(`INSERT INTO ${quoteIdent(table)} (${colList}) VALUES (${vals});`);
649	    }
650	  }
651	  lines.push("");
652	  lines.push("SET FOREIGN_KEY_CHECKS=1;");
653	  return {
654	    filename: data.truncated ? `${table}.first-${data.rows.length}-rows.sql` : `${table}.sql`,
655	    content: lines.join("\n"),
656	    mime: "application/sql",
657	    truncated: data.truncated,
658	  };
659	}
