810	/* ───────────────────────────────── Import ────────────────────────────────── */
811	
812	export type DbMgrImportStatement = { sql: string; ok: boolean; error: string | null; rows: number; elapsedMs: number };
813	export type DbMgrImportResult = { error?: string; results?: DbMgrImportStatement[]; ranAll?: boolean };
814	
815	/** Run a pasted / uploaded SQL script statement-by-statement. The script is split
816	 *  locally (quote/comment-aware) and each statement is shipped on its own through
817	 *  the scoped, capped `runScopedSql` transport (multipleStatements stays OFF — we
818	 *  never send a stacked query). Stops at the first error and reports per-statement
819	 *  results. Owner-or-admin + not-impersonating + rate-limited. */
820	export async function dbmgrImportSql(accountId: string, dbName: string, script: string): Promise<DbMgrImportResult> {
821	  const lt = await liveTarget(accountId, dbName);
822	  if ("error" in lt) return { error: lt.error };
823	  const text = String(script ?? "");
824	  if (!text.trim()) return { error: "Paste or upload a SQL script to import." };
825	  if (Buffer.byteLength(text, "utf8") > MAX_SQL_BYTES * 8) return { error: "That script is too large to import here — split it into smaller files." };
826	  const statements = splitSqlStatements(text);
827	  if (statements.length === 0) return { error: "No runnable statements found." };
828	  if (statements.length > MAX_IMPORT_STATEMENTS) return { error: `Too many statements (${statements.length}); the import cap is ${MAX_IMPORT_STATEMENTS}. Split the file.` };
829	
830	  if (lt.mode === "sandbox") {
831	    return { results: statements.map((s) => ({ sql: s, ok: true, error: null, rows: 0, elapsedMs: 1 })), ranAll: true };
832	  }
833	
834	  const results: DbMgrImportStatement[] = [];
835	  for (const stmt of statements) {
836	    const res = await runScopedSql(lt.target, dbName, stmt);
837	    results.push({ sql: stmt, ok: !res.error, error: res.error, rows: res.rows.length, elapsedMs: res.elapsedMs });
838	    if (res.error) return { results, ranAll: false }; // stop at the first failure
839	  }
840	  return { results, ranAll: true };
841	}
