243	/** The scopes a customer may choose for a new login on this account: the whole
244	 *  plan, or any one of its websites. Derived from the account's REAL sites, so a
245	 *  scope that does not exist can never be offered. */
246	export async function listFtpScopes(accountId: string): Promise<{ key: string; label: string; path: string }[]> {
247	  const ctx = await ownedAccount(accountId);
248	  if ("error" in ctx) return [];
249	  const [subs, addons] = await Promise.all([
250	    db.hostingSubdomain.findMany({ where: { accountId, status: { not: "DELETING" } }, select: { id: true, label: true, fqdn: true } }),
251	    db.hostingAddonDomain.findMany({ where: { accountId, status: { not: "DELETING" } }, select: { id: true, domain: true } }),
252	  ]);
253	  const out = [
254	    { key: FTP_SCOPE_ACCOUNT, label: "Whole account — every website", path: "" },
255	    { key: "primary", label: `${ctx.a.primaryDomain} (main website)`, path: siteDirs({ kind: "primary" }).docroot },
256	  ];
257	  for (const s of subs) out.push({ key: `subdomain:${s.id}`, label: s.fqdn, path: siteDirs({ kind: "subdomain", label: s.label }).container });
258	  for (const d of addons) out.push({ key: `addon:${d.id}`, label: d.domain, path: siteDirs({ kind: "addon", domain: d.domain }).container });
259	  return out;
260	}
