280	/**
281	 * Mint an extra SFTP login confined to one folder.
282	 *
283	 * The confinement is a unix user plus an sshd `Match User … ChrootDirectory`
284	 * block written by the worker — the SAME mechanism that already confines the
285	 * account's own login, and validated with `sshd -t` before any reload. The panel
286	 * therefore never claims the scope is in force: the row is PENDING until the
287	 * node reports back, and the credentials list says so.
288	 *
289	 * The cap is counted inside a Serializable transaction for the same reason
290	 * createHostingDatabase counts inside one — two concurrent creates must not both
291	 * read a stale count.
292	 */
293	export async function createFtpUser(
294	  accountId: string,
295	  labelRaw: string,
296	  scopeKey: string,
297	  readOnly: boolean,
298	): Promise<{ ok?: boolean; error?: string; username?: string; password?: string }> {
299	  const ctx = await ownedAccount(accountId, { active: true });
300	  if ("error" in ctx) return { error: ctx.error };
301	  await assertNotImpersonating();
302	
303	  const label = String(labelRaw ?? "").trim().toLowerCase();
304	  if (!isValidFtpLabel(label)) {
305	    return { error: "Use 1–16 lowercase letters, numbers or hyphens for the login name." };
306	  }
307	  if (!isValidUnixUsername(ctx.a.username)) return { error: "This account isn’t ready for extra logins yet." };
308	
309	  // Resolve the scope to a real directory on THIS account. "account" is the home.
310	  let chrootPath = "";
311	  if (scopeKey !== FTP_SCOPE_ACCOUNT) {
312	    const site = await resolveSite(accountId, scopeKey);
313	    if (!site) return { error: "That website isn’t part of this account." };
314	    // The primary site's own container IS the account home, so scoping "primary"
315	    // to the home would silently be the whole plan. Confine it to public_html
316	    // instead — which is what the customer means by "just the main website".
317	    chrootPath = site.kind === "primary" ? site.docroot : site.container;
318	  }
319	  if (!isValidFtpChroot(chrootPath)) return { error: "That folder can’t be used for a scoped login." };
320	
321	  const username = ftpUsernameFor(ctx.a.username, label);
322	  // Validated with the SCOPED-login validator, not the account one — see
323	  // isValidFtpUsername for why they are two functions and not one.
324	  if (!isValidFtpUsername(username)) return { error: "That login name doesn’t make a valid system user." };
325	
326	  const password = randomBytes(18).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 24);
327	
328	  try {
329	    await db.$transaction(async (tx) => {
330	      const n = await tx.hostingFtpUser.count({ where: { accountId, status: { in: ["PENDING", "ACTIVE"] } } });
331	      if (n >= MAX_FTP_USERS) throw new Error("CAP");
332	      const row = await tx.hostingFtpUser.create({
333	        data: {
334	          accountId, username, label, scopeKey: scopeKey || FTP_SCOPE_ACCOUNT,
335	          chrootPath, readOnly: !!readOnly,
336	          passwordEnc: encryptSecret(password), status: "PENDING",
337	        },
